import re, os, sys, subprocess

ROOT = "/mnt/raid/home/yangshuangning/vuln_variant_search/experiments/clairvoyant_variant_search/runs/C6/public/snapshots/s03"

# helpers that can move/free/linearize the skb head
HELPERS = [
    r"pskb_may_pull\s*\(", r"__pskb_pull_tail\s*\(", r"pskb_expand_head\s*\(",
    r"skb_cow_head\s*\(", r"skb_cow\s*\(", r"skb_linearize\s*\(",
    r"pskb_trim\s*\(", r"pskb_carve\s*\(", r"__pskb_trim\s*\(",
    r"pskb_pull\s*\(", r"ip_defrag\s*\(", r"ip_options_rcv_srr\s*\(",
    r"ip_forward_options\s*\(", r"ip6_defrag\s*\(",
    r"NF_HOOK\s*\(", r"NF_HOOK_COND\s*\(", r"nf_hook\s*\(",
    r"xfrm4_input\s*\(", r"xfrm6_input\s*\(", r"xfrm_input\s*\(",
    r"skb_unclone\s*\(", r"skb_ensure_writable\s*\(", r"skb_linearize_offset\s*\(",
]
HELPER_RE = re.compile("|".join(HELPERS))

# save patterns: var = <something derived from skb data area>
SAVE_RES = [
    (r"(\w+)\s*=\s*(?:\([^)]*\)\s*)?skb_header_pointer\s*\(", "skb_header_pointer"),
    (r"(\w+)\s*=\s*(?:\([^)]*\)\s*)?skb->data\b", "skb->data"),
    (r"(\w+)\s*=\s*(?:\([^)]*\)\s*)?skb->head\b", "skb->head"),
    (r"(\w+)\s*=\s*(?:\([^)]*\)\s*)?skb_network_header\s*\(", "skb_network_header"),
    (r"(\w+)\s*=\s*(?:\([^)]*\)\s*)?skb_transport_header\s*\(", "skb_transport_header"),
    (r"(\w+)\s*=\s*(?:\([^)]*\)\s*)?skb_mac_header\s*\(", "skb_mac_header"),
    (r"(\w+)\s*=\s*(?:\([^)]*\)\s*)?(?:u8\s*\*|__be16\s*\*|__be32\s*\*|void\s*\*)?skb_tail_pointer\s*\(", "skb_tail_pointer"),
]

def functions(lines):
    """yield (start_idx, end_idx, name) chunks using column-0 brace heuristic"""
    start = None
    fname = None
    for i, ln in enumerate(lines):
        if ln.startswith("{"):
            if start is None:
                start = i
        elif ln.startswith("}"):
            if start is not None:
                yield (start, i, fname)
                start = None
                fname = None
        elif start is not None and fname is None:
            m = re.match(r"^[\w\*\s]+?(\w+)\s*\(", ln)
            if m and not ln.lstrip().startswith(("*", "*/", "//")):
                fname = m.group(1)

def scan_file(path):
    try:
        with open(path, "r", errors="replace") as f:
            lines = f.readlines()
    except Exception:
        return []
    out = []
    for (s, e, fname) in functions(lines):
        body = lines[s:e+1]
        # collect helper call line offsets within function
        helper_lines = []
        for j in range(len(body)):
            if HELPER_RE.search(body[j]):
                helper_lines.append(j)
        if not helper_lines:
            continue
        # collect saves
        saves = {}  # var -> list of (line_idx, kind)
        for j in range(len(body)):
            for pat, kind in SAVE_RES:
                for m in re.finditer(pat, body[j]):
                    v = m.group(1)
                    if len(v) <= 2:  # skip 'p' etc? keep, but skip casts like u8
                        pass
                    saves.setdefault(v, []).append((j, kind))
        if not saves:
            continue
        # for each save, check use after a helper line that is after the save
        for v, sv in saves.items():
            if len(v) < 2:
                continue
            use_re = re.compile(r"\b" + re.escape(v) + r"\s*(->|\[|\.|\)|,|\+|-|\)|\b)")
            for (sj, kind) in sv:
                for hl in helper_lines:
                    if hl <= sj:
                        continue
                    # look for use of v between helper line and end of function
                    for u in range(hl+1, len(body)):
                        line = body[u]
                        if line.strip().startswith(("*", "/*", "//", "#")):
                            continue
                        if use_re.search(line):
                            # skip pure reassignment of v (v = ...)
                            if re.match(r"\s*" + re.escape(v) + r"\s*=[^=]", line):
                                continue
                            out.append({
                                "file": path, "func": fname,
                                "save_line": s+1+sj, "save_kind": kind, "var": v,
                                "helper_line": s+1+hl,
                                "use_line": s+1+u,
                                "save_src": body[sj].rstrip()[:150],
                                "helper_src": body[hl].rstrip()[:150],
                                "use_src": line.rstrip()[:150],
                            })
                            break
                    break  # only first helper after save (avoid dup explosion)
    return out

files = subprocess.run(["find", os.path.join(ROOT, "net"), os.path.join(ROOT, "drivers/net"),
                        "-name", "*.c", "-type", "f"], capture_output=True, text=True).stdout.split()

results = []
for p in files:
    results.extend(scan_file(p))

import json
with open(os.path.join(os.environ.get("TMPDIR", "/tmp"), "i034", "hits.json"), "w") as f:
    json.dump(results, f, indent=1)
print(len(results), "candidate triples")
